import json
h,w=12,26
out=[[9]*w for _ in range(h)]
p=[7,7,5,7,5]
centers={0:[12,19],1:[4],2:[20],3:[7],4:[21],6:[3,18],8:[11],10:[2],11:[14]}
# Template itself remains at row 4, columns 12..16.
for c in range(12,17): out[4][c]=p[c-12]
for r,cs in centers.items():
    for c in cs:
        for j,v in enumerate(p):
            x=c-2+j
            if 0<=x<w: out[r][x]=v
print(json.dumps(out))
